"""MCP後処理の新入力・因果要因・費用を初出力前に登録する。"""
from pathlib import Path
import sys,json,ast,hashlib,shutil
ROOT=Path(__file__).resolve().parent
sys.path.insert(0,str(ROOT/'campaigns/nas-pitch-measurement-20261008-v1'))
from temporary_storage import ManagedStorageBudget as Budget
from budget import read,digest,encode
HERE=ROOT/'campaigns/nas-mcp-postfilter-20261008-v1'
PREVIOUS=ROOT/'campaigns/nas-vocoder-f0-20261008-v1'
NAME='mcp-postfilter-v1'
sources=json.loads("{\"paths.py\":\"\\\"\\\"\\\"MCP後処理実験の論理位置。旧成果は読み取り専用で参照する。\\\"\\\"\\\"\\nfrom pathlib import Path\\nimport sys\\nHERE = Path(__file__).resolve().parent\\nROOT = HERE.parents[1]\\nREPO = ROOT.parents[2]\\nsys.path.insert(0, str(ROOT))\\nfrom budget import read, digest, encode\\nfrom temporary_storage import ManagedStorageBudget as Budget\\nNAME = 'mcp-postfilter-v1'\\nPREVIOUS = ROOT / 'campaigns/nas-vocoder-f0-20261008-v1'\\nTIMING = ROOT / 'campaigns/nas-post-mlpg-timing-20261005-v1'\\nSOURCE = ROOT / 'campaigns/nas-source-identity-20261004-v1'\\nWORLD = ROOT / 'campaigns/nas-world-control-20261004-v1'\\nOLD = REPO / 'research/experiments/autonomous-speech-synthesis'\\nPILOT = REPO / 'research/experiments/neural-control-distillation'\\nBUNDLE = REPO / 'research/experiments/neural-control-extension/results/nas-extension-20261002-v1/acoustic-revision/bundle'\\nPYTHON = OLD / '.venv-eval/bin/python'\\n\",\"temporary_storage.py\":\"\\\"\\\"\\\"外部の専用一時領域を共有予約・所有記録・不要時削除につなぐ。\\\"\\\"\\\"\\nfrom contextlib import contextmanager\\nimport os\\nfrom pathlib import Path\\nimport uuid\\nfrom storage_budget import StorageBudget\\n\\n\\nclass ManagedStorageBudget(StorageBudget):\\n    def _check(self, state, extra=0, campaign=None, tier='internal'):\\n        pending = sum(w['maximum_bytes'] for w in state.get('temporary_work', {}).values()\\n                      if w['status'] != 'removed')\\n        super()._check(state, extra + pending, campaign, tier)\\n\\n    def _owned(self, value):\\n        self.guard.check()\\n        base = self.guard.root / 'work' / self.storage['cycle_directory']\\n        path = Path(value['path'])\\n        if path.parent != base or path.name != value['owner'] or path.is_symlink():\\n            raise RuntimeError('一時領域の所有・実パスが不一致')\\n        if path.exists() and path.stat().st_dev != self.guard.device:\\n            raise RuntimeError('一時領域が別媒体')\\n        return path\\n\\n    def cleanup(self, owner):\\n        with self.locked():\\n            state = self._load()\\n            value = state['temporary_work'][owner]\\n            if value['status'] == 'removed':\\n                return\\n            value['status'] = 'cleanup_pending'\\n            self.event(state, dict(kind='temporary-cleanup-start', owner=owner))\\n            self._write_state(state)\\n        path = self._owned(value)\\n        files, directories = [], []\\n        if path.exists():\\n            for current, dirs, names in os.walk(path, followlinks=False):\\n                for name in dirs:\\n                    item = Path(current) / name\\n                    if item.is_symlink():\\n                        raise RuntimeError('未許可の一時ディレクトリリンク。削除を保留')\\n                    directories.append(item)\\n                for name in names:\\n                    item = Path(current) / name\\n                    if item.is_symlink() or not item.is_file():\\n                        raise RuntimeError('未許可の一時ファイル種別。削除を保留')\\n                    stat = item.stat()\\n                    files.append(dict(relative=str(item.relative_to(path)), bytes=stat.st_size,\\n                                      inode=stat.st_ino, device=stat.st_dev))\\n        actual = sum(v['bytes'] for v in files)\\n        over = actual > value['maximum_bytes']\\n        # 自分の排他的領域で作られた実ファイルだけを、削除前にmanifestへ登録する。\\n        with self.locked():\\n            state = self._load()\\n            state['temporary_work'][owner].update(files=files, observed_bytes=actual,\\n                                                 peak_violation=over)\\n            state['write_bytes'] += max(0, actual - value['maximum_write_bytes'])\\n            self.event(state, dict(kind='temporary-owned-files', owner=owner, files=files,\\n                                  observed_bytes=actual, peak_violation=over))\\n            self._write_state(state)\\n        for item in files:\\n            self.guard.check()\\n            target = path / item['relative']\\n            stat = target.lstat()\\n            if target.is_symlink() or (stat.st_ino, stat.st_dev, stat.st_size) != (\\n                    item['inode'], item['device'], item['bytes']):\\n                raise RuntimeError('一時ファイルが削除前に変化。削除を保留')\\n            target.unlink()\\n        for directory in sorted(directories, key=lambda p: len(p.parts), reverse=True):\\n            directory.rmdir()\\n        if path.exists():\\n            path.rmdir()\\n        assert not os.path.lexists(path)\\n        with self.locked():\\n            state = self._load()\\n            state['temporary_work'][owner].update(status='removed', removed_files=len(files),\\n                                                 remaining_bytes=0, absence_verified=True)\\n            self.event(state, dict(kind='temporary-cleanup-complete', owner=owner,\\n                                  files=len(files), bytes=actual, absence_verified=True,\\n                                  consumed_write_bytes_not_refunded=True))\\n            self._write_state(state)\\n        if over:\\n            raise RuntimeError('一時領域の予約超過。違反を保持し自分の不要物は削除済み')\\n\\n    def recover(self):\\n        state = self.snapshot()\\n        for owner, value in state.get('temporary_work', {}).items():\\n            if value['status'] != 'removed':\\n                if value['job'] in state['jobs']:\\n                    raise RuntimeError('一時領域を使用するジョブが未終了。新規作業を停止')\\n                self.cleanup(owner)\\n\\n    @contextmanager\\n    def workspace(self, job, purpose, maximum_bytes=8_000_000,\\n                  maximum_write_bytes=16_000_000):\\n        if maximum_bytes <= 0 or maximum_write_bytes < maximum_bytes:\\n            raise ValueError('一時容量と累積書込予約が不正')\\n        self.guard.check()\\n        owner = 'mcp-postfilter-' + uuid.uuid4().hex\\n        path = self.guard.root / 'work' / self.storage['cycle_directory'] / owner\\n        with self.locked():\\n            state = self._load()\\n            if any(v['status'] != 'removed' for v in state.get('temporary_work', {}).values()):\\n                raise RuntimeError('先行一時領域を照合・回収してから新規作業を開始')\\n            record = state['jobs'][job]\\n            if maximum_bytes > record['reserve_bytes']:\\n                raise RuntimeError('一時領域の事前予約不足')\\n            record['reserve_bytes'] -= maximum_bytes\\n            self._check(state, maximum_bytes, record['campaign'], tier='external')\\n            state['write_bytes'] += maximum_write_bytes\\n            state.setdefault('temporary_work', {})[owner] = dict(\\n                owner=owner, job=job, campaign=record['campaign'], path=str(path), purpose=purpose,\\n                maximum_bytes=maximum_bytes, maximum_write_bytes=maximum_write_bytes,\\n                status='reserved', creation_scope='排他的な所有ディレクトリ以下の通常ファイル',\\n                delete_when='子の終了・wait、全ハンドルclose後。成功・失敗とも不要時に削除。')\\n            self.event(state, dict(kind='temporary-reserved', **state['temporary_work'][owner]))\\n            self._write_state(state)\\n        try:\\n            with self.guard.parent_fd(str((path / 'owner-placeholder').relative_to(self.guard.root))):\\n                pass\\n            self._owned(dict(path=str(path), owner=owner))\\n            env = dict(os.environ)\\n            env.update({key: str(path) for key in (\\n                'TMPDIR', 'TMP', 'TEMP', 'XDG_CACHE_HOME', 'HF_HOME', 'MPLCONFIGDIR',\\n                'NUMBA_CACHE_DIR', 'TORCH_HOME')})\\n            env.update(PYTHONDONTWRITEBYTECODE='1', HF_HUB_OFFLINE='1',\\n                       TRANSFORMERS_OFFLINE='1', TOKENIZERS_PARALLELISM='false')\\n            yield path, env\\n        finally:\\n            self.cleanup(owner)\\n\\n    def reconcile(self):\\n        state = self.snapshot()\\n        for value in state.get('temporary_work', {}).values():\\n            if value['status'] != 'removed':\\n                raise RuntimeError('一時領域が未回収。照合を完了できない')\\n            if os.path.lexists(value['path']):\\n                raise RuntimeError('削除済み一時領域が再出現')\\n        return super().reconcile()\\n\",\"build.py\":\"\\\"\\\"\\\"外部の所有一時領域を使い、対応版C入口だけを構築する。\\\"\\\"\\\"\\nfrom paths import *\\nimport subprocess\\ndef main():\\n    b=Budget();b.recover()\\n    tool=Path('/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin/clang')\\n    sdk=Path('/Applications/Xcode.app/Contents/Developer/Platforms/MacOSX.platform/Developer/SDKs/MacOSX.sdk')\\n    assert tool.is_file() and sdk.is_dir()\\n    cmd=[str(tool),'-dynamiclib','-O2','-fno-modules','-undefined','dynamic_lookup','-isysroot',str(sdk),'-I'+str(HERE/'vendor'),str(HERE/'postfilter.c'),'-o',str(HERE/'postfilter.dylib')]\\n    with b.job(NAME,'setup','MCP後処理入口のC build',reserve_bytes=20000000) as job:\\n        with b.workspace(job,'clang中間物とcache',16000000,32000000) as (work,env):\\n            env['CLANG_MODULE_CACHE_PATH']=str(work/'clang-modules')\\n            with b.external_output(HERE/'postfilter.dylib',100000,job):\\n                result=subprocess.run(cmd,env=env,text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE,check=True,timeout=120)\\n        b.save(HERE/'build-audit.json',dict(command=cmd,returncode=result.returncode,stdout=result.stdout,stderr=result.stderr,source_sha256=digest(HERE/'postfilter.c'),binary_sha256=digest(HERE/'postfilter.dylib'),temporary_removed=True,new_download=0),job)\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__': main()\\n\",\"prepare.py\":\"\\\"\\\"\\\"入力履歴・共有ランタイム・ゲート・ソースを、最初の波形前に固定する。\\\"\\\"\\\"\\nfrom paths import *\\nimport argparse\\nimport json\\nimport re\\nimport subprocess\\nimport unicodedata\\n\\n\\ndef norm(value):\\n    return re.sub(r'[\\\\W_]', '', unicodedata.normalize('NFKC', value))\\n\\n\\ndef collect(value, texts, labels):\\n    if isinstance(value, dict):\\n        if isinstance(value.get('text'), str):\\n            texts.add(norm(value['text']))\\n        if value.get('full_context_labels'):\\n            labels.add(tuple(value['full_context_labels']))\\n        for item in value.values():\\n            collect(item, texts, labels)\\n    elif isinstance(value, list):\\n        for item in value:\\n            collect(item, texts, labels)\\n\\n\\ndef prepare():\\n    b = Budget()\\n    b.recover()\\n    reg = read(HERE / 'registration.json')\\n    assert digest(ROOT / 'mcp-postfilter-candidate-pool-0001.json') == reg['input_pool_sha256']\\n    with b.job(NAME, 'setup', '入力履歴と共有資産を波形前固定', reserve_bytes=12_000_000) as job:\\n        bundle = HERE / 'runtime-bundle'\\n        mapping={n:PREVIOUS/'runtime-bundle'/n for n in read(PREVIOUS/'runtime-bundle/manifest.json')['files']}\\n        mapping.update({n:HERE/n for n in ['runtime.py','runtime_batch.py','controls_v2.py','postfilter.py','postfilter.c','postfilter.dylib']})\\n        for name, source in mapping.items():\\n            b.write(bundle / name, source.read_bytes(), job)\\n        b.save(bundle / 'manifest.json', dict(files={n: digest(bundle / n) for n in mapping},\\n            shared_assets=True, final_non_neural=True, utterance_tables=0,\\n            waveform_lookup=0, neural_model=0, quality_certified=False), job)\\n    # 初期化前に外部TMPを指定した子で辞書による入力照合を行う。\\n    with b.job(NAME, 'setup', '新入力16の非衝突・ラベル上限確認', reserve_bytes=12_000_000) as job:\\n        with b.workspace(job, '辞書初期化と入力履歴の照合') as (work, env):\\n            result = subprocess.run([str(PYTHON), '-B', str(HERE / 'prepare.py'), '--inputs'],\\n                env=env, text=True, stdout=subprocess.PIPE, check=True)\\n        value = json.loads(result.stdout)\\n        b.save(HERE / 'novelty-audit.json', value['audit'], job)\\n        b.save(HERE / 'protocol.json', dict(registration_sha256=digest(HERE / 'registration.json'),\\n            rows=value['rows'], variants=reg['variants'], conditions=reg['conditions'],\\n            expected_records=256, protected_confirmation_opened=False,\\n            no_optimization_after_first_audio=True, quality_certified=False), job)\\n        b.save(HERE / 'engine-contract.json', read(PREVIOUS / 'engine-contract.json'), job)\\n    sources = sorted(p for p in HERE.glob('*.py'))\\n    with b.job(NAME, 'setup', '実行契約・固定一時方針を波形前封印', reserve_bytes=200_000) as job:\\n        b.save(HERE / 'execution-contract.json', dict(\\n            protocol_sha256=digest(HERE / 'protocol.json'),\\n            registration_sha256=digest(HERE / 'registration.json'),\\n            source_hashes={p.name: digest(p) for p in sources},\\n            runtime_manifest_sha256=digest(bundle / 'manifest.json'),\\n            engine_contract_sha256=digest(HERE / 'engine-contract.json'),\\n            output_gain=.25, native_half_tone='12*log2(requestedHz/220)',\\n            absolute_calibration='補完後の有声LF0へ一律log偏移、原有声相対輪郭保持',\\n            fill_rule=reg['fill_rule'], renderer_rule=reg['factor_rules'], AP_noise_power_factor=1.,MCP_postfilter_beta=[0.,.2],alpha=.55,energy_log_ratio_tolerance=1e-10,\\n            factor_baseline_byte_exact=True, renderer=['WORLD','HTS-pulse-noise-MLSA'],\\n            waveform_transfer='pipe/メモリ。子の一時音声ファイルなし。',\\n            tmp_maximum_bytes=8_000_000, tmp_maximum_write_bytes=16_000_000,\\n            fixed_before_first_wave=True, quality_certified=False), job)\\n    print('入力16・共有bundle・生成前契約の固定完了', flush=True)\\n    print(b.reconcile(), flush=True)\\n\\n\\ndef inputs():\\n    import os\\n    import sys\\n    import tempfile\\n    assert Path(tempfile.gettempdir()).resolve() == Path(os.environ['TMPDIR']).resolve()\\n    sys.path.insert(0, str(HERE / 'runtime-bundle'))\\n    from japanese_frontend import analyze\\n    import pyopenjtalk\\n    history = dict(read(PREVIOUS / 'novelty-audit.json')['history_reference_hashes'])\\n    for directory in (ROOT / 'campaigns').iterdir():\\n        if directory == HERE:\\n            continue\\n        for name in ['protocol.json']:\\n            path = directory / name\\n            if path.exists():\\n                history[str(path.relative_to(REPO))] = digest(path)\\n    for name in ['protocol.json', 'novelty-audit.json']:\\n        path = PREVIOUS / name\\n        history[str(path.relative_to(REPO))] = digest(path)\\n    texts, labels = set(), set()\\n    for name, expected in history.items():\\n        assert not re.search('splits|protected|holdout|final-confirm', name, re.I)\\n        assert digest(REPO / name) == expected, name\\n        collect(read(REPO / name), texts, labels)\\n    pool = read(ROOT / 'mcp-postfilter-candidate-pool-0001.json')\\n    rows, audit = [], []\\n    for length in ['short', 'long']:\\n        selected = []\\n        for text in pool['candidate_pool_' + length]:\\n            row = analyze(text)\\n            collision = norm(text) in texts or tuple(row['full_context_labels']) in labels\\n            valid = 3 <= len(row['full_context_labels']) <= 122\\n            chosen = not collision and valid and len(selected) < 8\\n            audit.append(dict(text=text, length=length, collision=collision,\\n                label_count=len(row['full_context_labels']), selected=chosen))\\n            if chosen:\\n                selected.append(row)\\n                texts.add(norm(text))\\n                labels.add(tuple(row['full_context_labels']))\\n        assert len(selected) == 8, '生成前に入力不足で停止'\\n        for group, row in enumerate(selected):\\n            row.update(id='mcp-fresh-' + str(len(rows)).zfill(2), length=length,\\n                challenge_group=group, cohort='prospective_once', kana=pyopenjtalk.g2p(row['text'], kana=True))\\n            rows.append(row)\\n    print(json.dumps(dict(rows=rows, audit=dict(history_reference_hashes=history,\\n        pool_checked_before_output=audit, selected_rows=[dict(id=r['id'], text=r['text'], kana=r['kana'])\\n        for r in rows], protected_confirmation_opened=False, final_quality_independence_claim=False)),\\n        ensure_ascii=False))\\n\\n\\nif __name__ == '__main__':\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument('--inputs', action='store_true')\\n    args = parser.parse_args()\\n    inputs() if args.inputs else prepare()\\n\",\"runtime.py\":\"\\\"\\\"\\\"文章入力の非ニューラル生成。同じMCP後処理をWORLDとHTSに渡す。\\\"\\\"\\\"\\nimport argparse\\nimport base64\\nimport hashlib\\nimport io\\nimport json\\nimport math\\nfrom pathlib import Path\\nimport sys\\nROOT = Path(__file__).resolve().parent\\nsys.path.insert(0, str(ROOT))\\nimport numpy as np\\nfrom scipy.io import wavfile\\nfrom japanese_frontend import analyze\\nfrom timing_engine import Engine\\nfrom world_renderer2 import synthesize as world_synthesize\\nfrom hts_arrays import synthesize as hts_synthesize\\nfrom controls_v2 import transform\\nMETHODS=['native','postfilter','voicing','voicing_postfilter','hts_native','hts_postfilter','hts_voicing','hts_voicing_postfilter']\\nfrom postfilter import transform_mcp\\nfrom calibration import calibrated_lf0\\nfrom acoustics import evaluate\\n\\n\\ndef ah(value):\\n    return hashlib.sha256(np.asarray(value, dtype='<f8').tobytes()).hexdigest()\\n\\n\\ndef verify():\\n    for name, expected in json.loads((ROOT / 'manifest.json').read_text())['files'].items():\\n        assert hashlib.sha256((ROOT / name).read_bytes()).hexdigest() == expected, name\\n\\n\\ndef generate(text, method, speed, pitch, full=False):\\n    if method not in list(METHODS):\\n        raise ValueError('未登録の方式')\\n    row = analyze(text)\\n    with Engine(row, ROOT / 'mei_normal.htsvoice', speed=speed,\\n                half_tone=12 * math.log2(pitch / 220)) as engine:\\n        before = engine.snapshot()\\n        variance = engine.variance()\\n        settings = engine.get_settings()\\n        native = engine.parameters()\\n        base=method[4:] if method.startswith('hts_') else method\\n        lf0_method='voicing' if 'voicing' in base else 'native'\\n        params,control,relative_error,invariants=transform(lf0_method,native,row['full_context_labels'],before['duration'],pitch)\\n        beta=.2 if 'postfilter' in base else 0.\\n        params[0],mcp_control=transform_mcp(params[0],beta)\\n        invariants=bool(invariants and mcp_control['energy_invariant_pass'])\\n        control.update(MCP_postfilter=mcp_control,LF0_method=lf0_method)\\n        voiced=params[1][:,0]>0\\n        assert control['AP_noise_power_factor']==1.\\n        if method.startswith('hts_'):\\n            raw,conversion=hts_synthesize(params,settings)\\n        else:\\n            raw,conversion=world_synthesize(params,settings)\\n            conversion.update(renderer='WORLD',AP_noise_power_factor=1.,input_streams_unchanged=True)\\n        assert engine.snapshot() == before and np.array_equal(engine.variance(), variance)\\n        assert engine.get_settings() == settings\\n    audio = (raw * .25).astype(np.float32)\\n    e0 = evaluate(audio, {}, 24000)\\n    # 波形は保存し、不通過も分母に残す。E0の不通過は条件の変更で救済しない。\\n    forbidden = [n for n in sys.modules if n.split('.')[0] in (\\n        'torch', 'tensorflow', 'transformers', 'faster_whisper', 'ctranslate2',\\n        'onnxruntime', 'sherpa_onnx')]\\n    assert not forbidden\\n    output = io.BytesIO()\\n    wavfile.write(output, 24000, audio)\\n    data = output.getvalue()\\n    meta = dict(sha256=hashlib.sha256(data).hexdigest(), synthesis_calls=1, E0_calls=1,\\n                E0=e0, E0_pass=e0['E0_pass'], invariants_pass=bool(invariants),\\n                relative_LF0_max_abs_error=relative_error, control=control,\\n                duration=before['duration'], msd=before['msd'], settings=settings,\\n                state_sha256=hashlib.sha256(json.dumps(before, sort_keys=True).encode()).hexdigest(),\\n                variance_sha256=ah(variance), native_parameter_hashes=[ah(v) for v in native],\\n                output_parameter_hashes=[ah(v) for v in params],\\n                output_gain=.25, conversion=conversion, forbidden_imports=forbidden,\\n                runtime_neural=False, teacher_audio=0, utterance_tables=0,\\n                generated_lf0_median_hz=float(np.exp(np.median(params[1][voiced, 0]))))\\n    return (data, meta, params, row) if full else (data, meta)\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument('--text', required=True)\\n    parser.add_argument('--method', choices=list(METHODS), required=True)\\n    parser.add_argument('--speed', type=float, required=True)\\n    parser.add_argument('--pitch', type=float, required=True)\\n    args = parser.parse_args()\\n    verify()\\n    data, meta = generate(args.text, args.method, args.speed, args.pitch)\\n    print(json.dumps(dict(meta=meta, wav_base64=base64.b64encode(data).decode()), allow_nan=False))\\n\\n\\nif __name__ == '__main__':\\n    main()\\n\",\"runtime_batch.py\":\"\\\"\\\"\\\"全件を実生成し、pipeで一つのarchiveを返す。一時音声を作らない。\\\"\\\"\\\"\\nimport base64\\nimport io\\nimport json\\nfrom pathlib import Path\\nimport sys\\nimport zipfile\\nsys.path.insert(0, str(Path(__file__).resolve().parent))\\nfrom runtime import generate, verify\\n\\n\\ndef main():\\n    rows = json.loads(sys.stdin.read())\\n    assert len(rows) == 256\\n    verify()\\n    output = io.BytesIO()\\n    records = []\\n    with zipfile.ZipFile(output, 'w', compression=zipfile.ZIP_DEFLATED, compresslevel=1) as archive:\\n        for request in rows:\\n            data, meta = generate(request['text'], request['method'], request['speed'], request['pitch'])\\n            archive.writestr(request['id'] + '.wav', data)\\n            archive.writestr(request['id'] + '.json', json.dumps(meta, allow_nan=False))\\n            records.append(dict(id=request['id'], **meta))\\n        archive.writestr('manifest.json', json.dumps(dict(records=records,\\n            synthesis_calls=len(rows), E0_calls=len(rows), no_generation_deduplication=True)))\\n    print(base64.b64encode(output.getvalue()).decode())\\n\\n\\nif __name__ == '__main__':\\n    main()\\n\",\"controller.py\":\"\\\"\\\"\\\"予約・pipe・外部一時領域を統一し、凍結比較を段階実行する。\\\"\\\"\\\"\\nfrom paths import *\\nimport argparse\\nimport base64\\nimport hashlib\\nimport io\\nimport json\\nimport os\\nimport subprocess\\nimport sys\\nimport time\\nimport zipfile\\n\\n\\ndef verify():\\n    contract=read(HERE/'execution-contract.json')\\n    assert digest(HERE/'protocol.json')==contract['protocol_sha256']\\n    assert digest(HERE/'registration.json')==contract['registration_sha256']\\n    assert digest(HERE/'runtime-bundle/manifest.json')==contract['runtime_manifest_sha256']\\n    for name,expected in contract['source_hashes'].items(): assert digest(HERE/name)==expected,name\\n    return contract\\n\\n\\ndef requests():\\n    p = read(HERE / 'protocol.json')\\n    return [dict(id=row['id'] + '/' + c + '/' + method, text=row['text'],\\n                 method=method, speed=q['speed'], pitch=q['requested_f0'])\\n            for row in p['rows'] for c, q in p['conditions'].items() for method in p['variants']]\\n\\n\\ndef profile(b, work, isolated):\\n    text = '(version 1)\\\\n(allow default)\\\\n(deny network*)\\\\n(deny file-write*)\\\\n'\\n    text += '(allow file-write* (subpath ' + json.dumps(str(work)) + '))\\\\n'\\n    if isolated:\\n        text += '(deny file-read* (subpath ' + json.dumps(str(REPO / 'research')) + '))\\\\n'\\n        text += '(deny file-read-data (subpath ' + json.dumps(str(b.guard.root)) + '))\\\\n'\\n        site = OLD / '.venv-eval/lib/python3.11/site-packages'\\n        allowed = [OLD / '.venv-eval', HERE / 'runtime-bundle', work]\\n        text += '(allow file-read* ' + ''.join('(subpath ' + json.dumps(str(p)) + ') ' for p in allowed) + ')\\\\n'\\n        text += '(allow file-read-data (literal ' + json.dumps(str(b.guard.root / 'identity.json')) + '))\\\\n'\\n        text += '(deny file-read* ' + ''.join('(subpath ' + json.dumps(str(site / n)) + ') '\\n            for n in ('torch', 'tensorflow', 'transformers', 'faster_whisper', 'ctranslate2',\\n                      'onnxruntime', 'sherpa_onnx')) + ')\\\\n'\\n    if isolated:\\n        ancestors=set()\\n        for path in [OLD / '.venv-eval', HERE / 'runtime-bundle', work]: ancestors.update(path.parents)\\n        text += '(allow file-read-metadata ' + ''.join('(literal ' + json.dumps(str(p)) + ') ' for p in sorted(ancestors)) + ')\\\\n'\\n    return text\\n\\n\\ndef execute(command, env, profile_text=None, input_text=None, timeout=1800):\\n    if profile_text:\\n        command = ['/usr/bin/sandbox-exec', '-p', profile_text, *command]\\n    # runはtimeout/失敗時も子を終了・waitし、pipeを閉じてから戻る。\\n    return subprocess.run(command, env=env, input=input_text, text=True,\\n                          stdout=subprocess.PIPE, check=True, timeout=timeout).stdout\\n\\n\\ndef save_exact(b,path,data,job):\\n    if path.exists():\\n        if path.suffix=='.npz':\\n            import numpy as np\\n            with np.load(path) as old, np.load(io.BytesIO(data)) as new:\\n                assert set(old.files)==set(new.files) and all(np.array_equal(old[k],new[k]) for k in old.files),str(path)\\n        else:assert digest(path)==hashlib.sha256(data).hexdigest(),str(path)\\n    else:b.write(path,data,job)\\n\\ndef comparison_worker(render_job, dsp_job):\\n    import tempfile\\n    assert Path(tempfile.gettempdir()).resolve() == Path(os.environ['TMPDIR']).resolve()\\n    sys.path.insert(0, str(HERE / 'runtime-bundle'))\\n    import numpy as np\\n    import re\\n    from scipy.io import wavfile\\n    from runtime import generate, verify as verify_bundle\\n    from measurement import measure, pitch_pass, ELIGIBLE, secondary\\n    verify_bundle()\\n    b = Budget()\\n    p = read(HERE / 'protocol.json')\\n    records = [];new_calls=0;reused_calls=0\\n    for row in p['rows']:\\n        for condition, q in p['conditions'].items():\\n            support = None\\n            native_meta = None\\n            by_method = {}\\n            for method in p['variants']:\\n                base = HERE / 'render' / row['id'] / condition / method\\n                if base.with_suffix('.json').exists():\\n                    record=read(base.with_suffix('.json'));assert record['protocol_sha256']==digest(HERE/'protocol.json') and record['id']==row['id']+'/'+condition+'/'+method\\n                    assert digest(REPO/record['wav'])==record['wav_sha256'] and record['status']=='completed'\\n                    meta=record['meta'];by_method[method]=meta;reused_calls+=1\\n                    if native_meta is None:native_meta=meta;support=record['measurement']['support']\\n                    records.append(dict(id=record['id'],record=str(base.with_suffix('.json').relative_to(REPO)),sha256=digest(base.with_suffix('.json'))));continue\\n                new_calls+=1\\n                data, meta, params, analyzed = generate(row['text'], method, q['speed'], q['requested_f0'], full=True)\\n                assert analyzed['full_context_labels'] == row['full_context_labels']\\n                if native_meta:\\n                    for key in ['duration', 'msd', 'settings', 'state_sha256', 'variance_sha256', 'native_parameter_hashes']:\\n                        assert meta[key] == native_meta[key], key\\n                    base_method=method[4:] if method.startswith('hts_') else method\\n                    if 'postfilter' not in base_method:assert meta['output_parameter_hashes'][0] == native_meta['output_parameter_hashes'][0]\\n                    else:assert meta['control']['MCP_postfilter']['beta']==.2\\n                    lf0_base='voicing' if 'voicing' in base_method else 'native'\\n                    if 'postfilter' in base_method:assert meta['output_parameter_hashes'][1]==by_method[lf0_base]['output_parameter_hashes'][1]\\n                    if base_method=='voicing_postfilter':assert meta['output_parameter_hashes'][0]==by_method['postfilter']['output_parameter_hashes'][0]\\n                    assert meta['output_parameter_hashes'][2] == native_meta['output_parameter_hashes'][2]\\n                else:\\n                    native_meta = meta\\n                if method.startswith('hts_'):\\n                    reference=by_method[method[4:]]\\n                    assert meta['output_parameter_hashes']==reference['output_parameter_hashes']\\n                    assert meta['generated_lf0_median_hz']==reference['generated_lf0_median_hz']\\n                    assert meta['conversion']['input_streams_unchanged']\\n                by_method[method]=meta\\n                save_exact(b,base.with_suffix('.wav'), data, render_job)\\n                arrays = io.BytesIO()\\n                np.savez_compressed(arrays, mcp=params[0], lf0=params[1], lpf=params[2], duration=meta['duration'])\\n                save_exact(b,base.with_suffix('.npz'), arrays.getvalue(), render_job)\\n                _, audio = wavfile.read(io.BytesIO(data))\\n                eligible = [i for i, label in enumerate(row['full_context_labels'])\\n                            if re.search(r'\\\\-([^+]+)\\\\+', label).group(1) in ELIGIBLE\\n                            and any(meta['msd'][i * 5:(i + 1) * 5][k] > .5 for k in range(5))]\\n                measured, f0, times = measure(audio, meta['duration'], eligible, support)\\n                if support is None:\\n                    support = measured['support']\\n                    support_path=HERE/'support'/row['id']/(condition+'.json')\\n                    support_value=dict(indices=support,excluded=[r['index'] for r in measured['eligible_native_intervals'] if not r['support_complete']],native_wave_sha256=meta['sha256'],fixed_from_native=True,not_candidate_selected=True)\\n                    if support_path.exists():assert read(support_path)==support_value\\n                    else:b.save(support_path,support_value,dsp_job)\\n                arrays = io.BytesIO()\\n                np.savez_compressed(arrays, f0=f0, times=times)\\n                save_exact(b,base.with_suffix('.dio.npz'), arrays.getvalue(), dsp_job)\\n                diagnostic,extra_arrays=secondary(audio,meta['duration'],support)\\n                extra=io.BytesIO();np.savez_compressed(extra,**extra_arrays)\\n                save_exact(b,base.with_suffix('.secondary.npz'),extra.getvalue(),dsp_job)\\n                record = {k: row[k] for k in ['text', 'length', 'challenge_group', 'cohort']}\\n                record.update(id=row['id'] + '/' + condition + '/' + method, condition=condition,\\n                    variant=method, wav=str(base.with_suffix('.wav').relative_to(REPO)),\\n                    wav_sha256=meta['sha256'], status='completed', meta=meta,\\n                    measurement=measured, secondary_diagnostic=diagnostic, pitch_gate=pitch_pass(measured, q['requested_f0']),\\n                    E0_pass=meta['E0_pass'], invariants_pass=meta['invariants_pass'],\\n                    protocol_sha256=digest(HERE / 'protocol.json'), quality_certified=False)\\n                b.write_data(base.with_suffix('.json'), encode(record), dsp_job)\\n                records.append(dict(id=record['id'], record=str(base.with_suffix('.json').relative_to(REPO)),\\n                                    sha256=digest(base.with_suffix('.json'))))\\n            print('比較', len(records), '/256', flush=True)\\n    assert len(records) == 256\\n    b.save(HERE / 'render-manifest.json', dict(rows=records, new_render_calls=new_calls,reused_render_records=reused_calls,\\n        new_DSP_calls=new_calls*5, no_optimization_after_output=True, quality_certified=False), dsp_job)\\n\\n\\ndef computation(stage):\\n    b = Budget()\\n    count=256\\n    dsp=1280\\n    with b.job(NAME, 'render', stage, count=count, reserve_bytes=200_000_000) as render_job:\\n        with b.job(NAME, 'dsp', stage + ' 固定測定', count=dsp, reserve_bytes=16_000_000) as dsp_job:\\n            with b.workspace(render_job, stage + ' ライブラリ初期化・必要時一時処理') as (_, env):\\n                execute([str(PYTHON), '-B', str(HERE / 'controller.py'),\\n                         stage + '-worker', '--render-job', render_job, '--dsp-job', dsp_job], env)\\n    print(stage, '保存完了', flush=True)\\n\\n\\ndef isolate():\\n    b = Budget()\\n    reqs = requests()\\n    expected = {r['id']: read(REPO / r['record'])['wav_sha256']\\n                for r in read(HERE / 'render-manifest.json')['rows']}\\n    outputs, profiles = {}, {}\\n    for mode in ['normal', 'isolated']:\\n        saved=HERE/('runtime-batch-'+mode+'.json')\\n        if saved.exists():\\n            value=read(saved);assert value['all_hash_match'] and len(value['records'])==256\\n            assert all(r['sha256']==expected[key] for key,r in value['records'].items())\\n            with zipfile.ZipFile(HERE/'runtime-archives'/(mode+'.zip')) as archive:\\n                assert len(archive.namelist())==513\\n                assert all(hashlib.sha256(archive.read(key+'.wav')).hexdigest()==expected[key] for key in value['records'])\\n            outputs[mode]=value['records'];profiles[mode]=value['profile'];continue\\n        with b.job(NAME, 'render', '通常/隔離batch256 ' + mode, count=256, reserve_bytes=200_000_000) as job:\\n            with b.job(NAME, 'dsp', '通常/隔離batch256 E0 ' + mode, count=256, reserve_bytes=100_000):\\n                with b.workspace(job, mode + ' ランタイム初期化') as (work, env):\\n                    sb = profile(b, work, mode == 'isolated')\\n                    output = execute([str(PYTHON), '-I', '-B', str(HERE / 'runtime-bundle/runtime_batch.py')],\\n                                     env, sb, json.dumps(reqs, ensure_ascii=False))\\n                    archive_data = base64.b64decode(output, validate=False)\\n                    profiles[mode] = dict(source=sb, sha256=hashlib.sha256(sb.encode()).hexdigest())\\n                b.write(HERE / 'runtime-archives' / (mode + '.zip'), archive_data, job)\\n                with zipfile.ZipFile(io.BytesIO(archive_data)) as archive:\\n                    manifest = json.loads(archive.read('manifest.json'))\\n                    assert len(manifest['records']) == 256\\n                    assert manifest['synthesis_calls'] == manifest['E0_calls'] == 256\\n                    assert len(archive.namelist()) == 513\\n                    records = {}\\n                    for r in manifest['records']:\\n                        data = archive.read(r['id'] + '.wav')\\n                        assert hashlib.sha256(data).hexdigest() == r['sha256'] == expected[r['id']]\\n                        assert r['synthesis_calls'] == r['E0_calls'] == 1 and not r['forbidden_imports']\\n                        records[r['id']] = r\\n                b.write_data(HERE / ('runtime-batch-' + mode + '.json'), encode(dict(records=records,\\n                    all_hash_match=True, profile=profiles[mode])), job)\\n                outputs[mode] = records\\n        print(mode, '256件のhash一致', flush=True)\\n    cli = []\\n    for request in [reqs[0], reqs[-1]]:\\n        for mode in ['normal', 'isolated']:\\n            cli_path=HERE/'runtime-cli'/mode/(request['id']+'.wav')\\n            if cli_path.exists():\\n                assert digest(cli_path)==expected[request['id']];cli.append(dict(id=request['id'],mode=mode,sha256=expected[request['id']],bit_match=True));continue\\n            with b.job(NAME, 'render', 'CLI ' + mode + '/' + request['id'], reserve_bytes=10_000_000) as job:\\n                with b.job(NAME, 'dsp', 'CLI E0 ' + mode, reserve_bytes=100_000):\\n                    with b.workspace(job, '単独CLI ライブラリ初期化') as (work, env):\\n                        output = json.loads(execute([str(PYTHON), '-I', '-B',\\n                            str(HERE / 'runtime-bundle/runtime.py'), '--text', request['text'],\\n                            '--method', request['method'], '--speed', str(request['speed']),\\n                            '--pitch', str(request['pitch'])], env, profile(b, work, mode == 'isolated')))\\n                    data = base64.b64decode(output['wav_base64'])\\n                    assert hashlib.sha256(data).hexdigest() == output['meta']['sha256'] == expected[request['id']]\\n                    b.write(HERE / 'runtime-cli' / mode / (request['id'] + '.wav'), data, job)\\n                    cli.append(dict(id=request['id'], mode=mode, sha256=output['meta']['sha256'], bit_match=True))\\n    # 禁止資料は、論理参照と外部の実体、現在の入力と出力の全てを実際に拒否する。\\n    logical = HERE / 'render/mcp-fresh-00/neutral/native.wav'\\n    blocked = [logical, logical.resolve(), HERE / 'protocol.json', HERE / 'registration.json',\\n               PREVIOUS / 'protocol.json', HERE / 'runtime-archives/normal.zip',\\n               (HERE / 'runtime-archives/normal.zip').resolve()]\\n    code = 'import json,socket; paths=' + repr([str(p) for p in blocked]) + '; a=[]\\\\n'\\n    code += \\\"for p in paths:\\\\n try:\\\\n  open(p,'rb').close();a.append(False)\\\\n except PermissionError:a.append(True)\\\\n\\\"\\n    code += \\\"s=socket.socket()\\\\ntry:s.bind(('127.0.0.1',0));net=False\\\\nexcept PermissionError:net=True\\\\nprint(json.dumps(dict(read_denied=a,network_denied=net)))\\\"\\n    with b.job(NAME, 'audit', '論理/物理資料と通信の実拒否', reserve_bytes=10_000_000) as job:\\n        with b.workspace(job, '拒否probe') as (work, env):\\n            proof = json.loads(execute([str(PYTHON), '-I', '-B', '-c', code], env, profile(b, work, True)))\\n        assert all(proof['read_denied']) and proof['network_denied']\\n        b.save(HERE / 'denial-probe.json', dict(proof, paths=[str(p) for p in blocked]), job)\\n        pairs = [dict(id=r['id'], bit_match=outputs['normal'][r['id']]['sha256'] ==\\n            outputs['isolated'][r['id']]['sha256']) for r in reqs]\\n        assert len(pairs) == 256 and all(r['bit_match'] for r in pairs)\\n        b.save(HERE / 'runtime-audit.json', dict(passed=True, pairs=pairs, CLI=cli,\\n            new_render_calls=516, new_DSP_calls=516, denial_probe=proof,\\n            final_non_neural=True, quality_certified=False), job)\\n    print('通常/隔離256組・CLI4件・読取/通信拒否を確認', flush=True)\\n\\n\\ndef asr(name):\\n    b = Budget()\\n    if (HERE/('asr-manifest-'+name+'.json')).exists():\\n        manifest=read(HERE/('asr-manifest-'+name+'.json'));assert len(manifest['rows'])==256 and all(digest(REPO/r['path'])==r['sha256'] for r in manifest['rows']);print(name,'保存済み256件のhashを確認');return\\n    assert read(HERE / 'runtime-audit.json')['passed']\\n    engine = read(HERE / 'engine-contract.json')\\n    with b.job(NAME, 'audit', 'ASRモデル・辞書・正規化hash照合 ' + name, reserve_bytes=100_000):\\n        for n, h in engine['asr_model_hashes'].items():\\n            assert digest(REPO / n) == h, n\\n        assert digest(OLD / 'diagnostics.py') == engine['normalizer_source_sha256']\\n        cfg = engine['reading_diagnostic']['contract']\\n        for n, h in cfg['dictionary_files'].items():\\n            assert digest(Path(cfg['dictionary_path']) / n) == h\\n        assert digest(cfg['library']) == cfg['library_sha256']\\n    with b.job(NAME, 'ai', '固定ASR256 ' + name, count=256, reserve_bytes=12_000_000) as job:\\n        with b.workspace(job, name + ' 認識器初期化・評価') as (work, env):\\n            result = json.loads(execute([str(PYTHON), '-B', str(HERE / 'asr_worker.py'),\\n                '--engine', name], env, profile(b, work, False)))\\n        assert len(result['rows']) == result['ai_calls'] == 256\\n        rows = []\\n        for value in result['rows']:\\n            target = HERE / 'asr' / name / (value['id'] + '.json')\\n            b.write_data(target, encode(value), job)\\n            rows.append(dict(path=str(target.relative_to(REPO)), sha256=digest(target)))\\n        b.save(HERE / ('asr-manifest-' + name + '.json'), dict(rows=rows, new_ai=256,\\n            reused=0, optimization_after_asr=False), job)\\n    print(name, '256件保存完了', flush=True)\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument('stage', choices=['comparison', 'isolate', 'asr', 'comparison-worker'])\\n    parser.add_argument('--engine', choices=['whisper', 'reazon'])\\n    parser.add_argument('--render-job')\\n    parser.add_argument('--dsp-job')\\n    args = parser.parse_args()\\n    verify()\\n    if args.stage.endswith('-worker'):\\n        globals()[args.stage.replace('-', '_')](args.render_job, args.dsp_job)\\n        return\\n    b = Budget()\\n    b.recover()\\n    if args.stage == 'comparison':\\n        computation(args.stage)\\n    elif args.stage == 'isolate':\\n        isolate()\\n    elif args.stage == 'asr':\\n        assert args.engine\\n        asr(args.engine)\\n    print(b.reconcile(), flush=True)\\n\\n\\nif __name__ == '__main__':\\n    main()\\n\",\"preflight.py\":\"\\\"\\\"\\\"波形前の境界検査と、登録済み4生成だけの互換fixture。\\\"\\\"\\\"\\nfrom paths import *\\nimport argparse,subprocess,json,base64,io,hashlib,os,sys,runpy,contextlib,zipfile,math\\ndef static_worker():\\n    import tempfile\\n    assert Path(tempfile.gettempdir()).resolve()==Path(os.environ['TMPDIR']).resolve()\\n    sys.path.insert(0,str(HERE/'runtime-bundle'))\\n    import numpy as np\\n    import hts_arrays as h\\n    import runtime_batch as rb\\n    assert not h._fn(None,None,None,0,0,0,None,0)\\n    cfg=dict(stage=0.,use_log_gain=0.,sampling_frequency=48000.,fperiod=240.,alpha=.55,beta=0.,volume=1.,audio_buff_size=0.,stop=0.)\\n    valid=[np.zeros((5,35)),np.full((5,1),np.log(220.)),np.tile([0.,1.,0.],(5,1))]\\n    assert all(np.array_equal(a,z) for a,z in zip(h.validated(valid,cfg),valid))\\n    bad=[]\\n    for stream in range(3):\\n        p=[x.copy() for x in valid];p[stream][0,0]=np.nan;bad.append((p,cfg))\\n    for stream,cols in [(0,34),(1,2),(2,2)]:\\n        p=[x.copy() for x in valid];p[stream]=np.zeros((5,cols));bad.append((p,cfg))\\n    for f0 in [-1.,0.,np.log(50.),np.log(900.)]:\\n        p=[x.copy() for x in valid];p[1][0,0]=f0;bad.append((p,cfg))\\n    changed=dict(cfg);changed['alpha']=.5;bad.append((valid,changed))\\n    p=[x.copy() for x in valid];p[2]=p[2][:-1];bad.append((p,cfg))\\n    for p,c in bad:\\n        try:h.validated(p,c)\\n        except ValueError:pass\\n        else:raise AssertionError('不正HTS入力を受理')\\n    from postfilter import transform_mcp,_fn as pf_fn\\n    assert not pf_fn(None,0,0,0.,None,None,None)\\n    z,detail=transform_mcp(valid[0],0.);assert z.tobytes()==valid[0].tobytes() and detail['energy_invariant_pass']\\n    z,detail=transform_mcp(valid[0],.2);assert detail['energy_invariant_pass']\\n    for beta in [-.2,.1,.4,float('nan')]:\\n        try:transform_mcp(valid[0],beta)\\n        except ValueError:pass\\n        else:raise AssertionError('未登録βを受理')\\n    before=[x.tobytes() for x in valid]\\n    out=np.zeros(5*240,dtype=float)\\n    assert not h._fn(*(x.ctypes.data_as(h.P) for x in valid),5,34,3,out.ctypes.data_as(h.P),len(out))\\n    assert [x.tobytes() for x in valid]==before\\n    rows=[dict(id='fixture/'+str(i),text='人工入力',method='native',speed=1.,pitch=220.) for i in range(256)]\\n    def fake(text,method,speed,pitch):\\n        data=b'artificial-no-wave'\\n        return data,dict(sha256=hashlib.sha256(data).hexdigest(),synthesis_calls=1,E0_calls=1,forbidden_imports=[],nested={'integer':1,'boolean':True,'indices':[1,2]})\\n    old=(rb.generate,rb.verify,sys.stdin)\\n    rb.generate=fake;rb.verify=lambda:None;sys.stdin=io.StringIO(json.dumps(rows))\\n    try:\\n        result=io.StringIO()\\n        with contextlib.redirect_stdout(result):rb.main()\\n    finally:rb.generate,rb.verify,sys.stdin=old\\n    data=base64.b64decode(result.getvalue().strip(),validate=True)\\n    with zipfile.ZipFile(io.BytesIO(data)) as archive:\\n        manifest=json.loads(archive.read('manifest.json'))\\n        assert len(archive.namelist())==513 and len(manifest['records'])==256\\n        assert manifest['synthesis_calls']==manifest['E0_calls']==256\\n        for row in manifest['records']:\\n            assert hashlib.sha256(archive.read(row['id']+'.wav')).hexdigest()==row['sha256']\\n            assert json.loads(archive.read(row['id']+'.json'))['nested']['boolean'] is True\\n    controls=io.StringIO()\\n    with contextlib.redirect_stdout(controls):runpy.run_path(str(HERE/'test_controls.py'),run_name='fixture_only')\\n    return dict(null_and_invalid_shapes_rejected=True,negative_cases=len(bad),settings_fixed=True,input_streams_preserved=True,batch256_roundtrip=True,base64_valid=True,controls=json.loads(controls.getvalue()),actual_render_calls=0,fixture_not_quality_evidence=True)\\ndef compat_worker():\\n    import tempfile\\n    assert Path(tempfile.gettempdir()).resolve()==Path(os.environ['TMPDIR']).resolve()\\n    sys.path.insert(0,str(HERE/'runtime-bundle'))\\n    import numpy as np\\n    from scipy.io import wavfile\\n    from runtime import generate,verify,analyze,Engine\\n    verify()\\n    prior=read(PREVIOUS/'protocol.json');row=prior['rows'][0];q=prior['conditions']['neutral']\\n    results=[]\\n    for method in ['native','voicing','hts_native','hts_voicing']:\\n        data,meta=generate(row['text'],method,q['speed'],q['requested_f0'])\\n        expected=read((PREVIOUS/'render'/row['id']/'neutral'/method).with_suffix('.json'))\\n        assert meta['sha256']==expected['wav_sha256']\\n        json.dumps(meta,allow_nan=False)\\n        results.append(dict(name='prior-'+method,sha256=meta['sha256'],bit_match=True,wav_base64=base64.b64encode(data).decode(),meta=meta))\\n    from controls_v2 import transform\\n    from postfilter import reference_synthesize\\n    for base,method in [('native','hts_postfilter'),('voicing','hts_voicing_postfilter')]:\\n        data,meta,params,analyzed=generate(row['text'],method,q['speed'],q['requested_f0'],full=True)\\n        with Engine(analyzed,HERE/'runtime-bundle/mei_normal.htsvoice',speed=q['speed'],half_tone=12*math.log2(q['requested_f0']/220)) as engine:\\n            native=engine.parameters();before=engine.snapshot();settings=engine.get_settings()\\n            original,_,_,_=transform(base,native,analyzed['full_context_labels'],before['duration'],q['requested_f0'])\\n            assert original[1].tobytes()==params[1].tobytes() and original[2].tobytes()==params[2].tobytes()\\n            raw=reference_synthesize(original,settings,.2)\\n            buf=io.BytesIO();wavfile.write(buf,24000,(raw*.25).astype(np.float32));reference=buf.getvalue()\\n        assert data==reference\\n        results.extend([dict(name=base+'-preprocess-beta02',sha256=hashlib.sha256(data).hexdigest(),bit_match=True,wav_base64=base64.b64encode(data).decode(),meta=meta),dict(name=base+'-internal-beta02',sha256=hashlib.sha256(reference).hexdigest(),bit_match=True,wav_base64=base64.b64encode(reference).decode())])\\n    return dict(results=results,actual_render_calls=8,prior_zero_beta_byte_exact=True,preprocess_internal_HTS_beta02_byte_exact=True,fixture_not_quality_evidence=True,quality_certified=False)\\n\\ndef main():\\n    p=argparse.ArgumentParser();p.add_argument('stage',choices=['static','compat','static-worker','compat-worker']);args=p.parse_args()\\n    if args.stage.endswith('-worker'):\\n        result=static_worker() if args.stage=='static-worker' else compat_worker()\\n        print(json.dumps(result,ensure_ascii=False,allow_nan=False));return\\n    from controller import verify\\n    verify();b=Budget();b.recover()\\n    existing=HERE/('preflight-static-audit.json' if args.stage=='static' else 'compatibility-fixture-audit.json')\\n    if existing.exists():print('保存済みfixtureを保持');return\\n    if args.stage=='static':\\n        with b.job(NAME,'audit','C入力境界・256件人工archive・制御メタデータ',reserve_bytes=12000000) as job:\\n            with b.workspace(job,'波形前の人工境界検査') as (_,env):\\n                out=subprocess.run([str(PYTHON),'-B',str(HERE/'preflight.py'),'static-worker'],env=env,text=True,stdout=subprocess.PIPE,check=True,timeout=120)\\n            b.save(HERE/'preflight-static-audit.json',json.loads(out.stdout),job)\\n    else:\\n        assert read(HERE/'preflight-static-audit.json')['actual_render_calls']==0\\n        with b.job(NAME,'render','登録済み旧WORLD/HTS全frame互換fixture',count=8,reserve_bytes=12000000) as job:\\n            with b.job(NAME,'dsp','8互換fixtureのstream/hash比較',count=8,reserve_bytes=100000) as dspjob:\\n                with b.workspace(job,'互換fixtureの生成・pipe受渡') as (_,env):\\n                    out=subprocess.run([str(PYTHON),'-B',str(HERE/'preflight.py'),'compat-worker'],env=env,text=True,stdout=subprocess.PIPE,check=True,timeout=300)\\n                result=json.loads(out.stdout)\\n                for item in result['results']:\\n                    audio=base64.b64decode(item.pop('wav_base64'),validate=True)\\n                    assert hashlib.sha256(audio).hexdigest()==item['sha256']\\n                    b.write(HERE/'fixtures'/(item['name']+'.wav'),audio,job)\\n                b.save(HERE/'compatibility-fixture-audit.json',result,dspjob)\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\",\"summarize.py\":\"\\\"\\\"\\\"全256音声・固定33群・二ASRを集計し、欠測と悪化を保持する。\\\"\\\"\\\"\\nfrom paths import *\\n\\n\\ndef grouped(pairs):\\n    groups = {}\\n    for condition in ['both', 'neutral', 'higher']:\\n        for group in ['all', 'short', 'long'] + ['group' + str(i) for i in range(8)]:\\n            chosen = [r for r in pairs if (condition == 'both' or r['condition'] == condition)\\n                and (group == 'all' or r['length'] == group or (\\n                    group.startswith('group') and r['challenge_group'] == int(group[5:])))]\\n            valid = [r for r in chosen if r['status'] == 'completed']\\n            errors = sum(r['errors'] for r in valid)\\n            native = sum(r['native_errors'] for r in valid)\\n            chars = sum(r['characters'] for r in valid)\\n            groups[condition + '/' + group] = dict(expected=len(chosen), missing=len(chosen)-len(valid),\\n                errors=errors, native_errors=native, characters=chars,\\n                non_worsening=bool(chosen) and len(valid) == len(chosen) and chars > 0 and errors <= native)\\n    assert len(groups) == 33\\n    return groups\\n\\n\\ndef negative_tests():\\n    assert not all(v['non_worsening'] for v in grouped([]).values())\\n    pairs = [dict(condition=c, length=l, challenge_group=g, status='completed',\\n        errors=0, native_errors=0, characters=10)\\n        for c in ['neutral', 'higher'] for l in ['short', 'long'] for g in range(8)]\\n    assert all(v['non_worsening'] for v in grouped(pairs).values())\\n    pairs[0]['status'] = 'missing'\\n    assert not all(v['non_worsening'] for v in grouped(pairs).values())\\n    pairs[0].update(status='completed', errors=1)\\n    assert not all(v['non_worsening'] for v in grouped(pairs).values())\\n    return dict(empty_missing_worse_rejected=True, fixture_not_quality_evidence=True)\\n\\n\\ndef main():\\n    from controller import verify\\n    verify()\\n    b = Budget()\\n    p = read(HERE / 'protocol.json')\\n    content, engineering, qualifications = {}, {}, {}\\n    runtime = read(HERE / 'runtime-audit.json')\\n    assert runtime['passed'] and len(runtime['pairs']) == 256 and len(runtime['CLI']) == 4\\n    with b.job(NAME, 'audit', '全音声・全群・欠測を固定分母で集計', reserve_bytes=6_000_000) as job:\\n        for method in p['variants']:\\n            measures = []\\n            for row in p['rows']:\\n                for condition in p['conditions']:\\n                    path = HERE / 'render' / row['id'] / condition / (method + '.json')\\n                    value = dict(id=row['id'] + '/' + condition + '/' + method,\\n                                 status='missing', required_pass=False)\\n                    if path.exists():\\n                        record = read(path)\\n                        assert digest(REPO / record['wav']) == record['wav_sha256']\\n                        value.update(status=record['status'], E0_pass=record['E0_pass'],\\n                            invariants_pass=record['invariants_pass'],\\n                            pitch_gate=record['pitch_gate'], measurement=record['measurement'], secondary_diagnostic=record['secondary_diagnostic'],\\n                            generated_lf0_median_hz=record['meta']['generated_lf0_median_hz'],\\n                            required_pass=record['status'] == 'completed' and record['E0_pass']\\n                            and record['invariants_pass'] and record['pitch_gate']['passed'])\\n                    measures.append(value)\\n            engineering[method] = dict(pairs=measures, expected=32,\\n                missing=sum(r['status'] != 'completed' for r in measures),\\n                E0_pass_count=sum(r.get('E0_pass', False) for r in measures),\\n                pitch_pass_count=sum(r.get('pitch_gate', {}).get('passed', False) for r in measures),\\n                all_required_pass=len(measures) == 32 and all(r['required_pass'] for r in measures))\\n            content[method] = {}\\n            for engine in ['whisper', 'reazon']:\\n                pairs = []\\n                for row in p['rows']:\\n                    for condition in p['conditions']:\\n                        pair = dict(text_id=row['id'], condition=condition, length=row['length'],\\n                                    challenge_group=row['challenge_group'], status='missing')\\n                        a = HERE / 'asr' / engine / row['id'] / condition / (method + '.json')\\n                        n = a.with_name('native.json')\\n                        if a.exists() and n.exists():\\n                            x, y = read(a), read(n)\\n                            if x['status'] == y['status'] == 'completed':\\n                                assert x['reference_kana'] == y['reference_kana']\\n                                assert x['characters'] == y['characters']\\n                                for r in [x, y]:\\n                                    assert r['protocol_sha256'] == digest(HERE / 'protocol.json')\\n                                    assert digest(REPO / r['wav']) == r['wav_sha256']\\n                                pair.update(status='completed', errors=x['errors'], native_errors=y['errors'],\\n                                    characters=x['characters'], candidate_hypothesis=x['hypothesis'],\\n                                    native_hypothesis=y['hypothesis'])\\n                        pairs.append(pair)\\n                groups = grouped(pairs)\\n                content[method][engine] = dict(pairs=pairs, groups=groups,\\n                    worsening_groups=[n for n, r in groups.items() if not r['non_worsening']],\\n                    all_groups_non_worsening=len(pairs) == 32 and all(r['non_worsening'] for r in groups.values()))\\n            qualifications[method] = engineering[method]['all_required_pass'] and all(\\n                v['all_groups_non_worsening'] for v in content[method].values()) and runtime['passed']\\n        factorial={}\\n        for metric in ['missing_support','DIO_error','ACF_error','whisper_errors','reazon_errors']:\\n            values={}\\n            for method in p['variants']:\\n                if metric.endswith('_errors'):\\n                    pairs=content[method][metric.split('_')[0]]['pairs']\\n                    values[method]=sum(r['errors'] for r in pairs) if all(r['status']=='completed' for r in pairs) else None\\n                else:\\n                    pairs=engineering[method]['pairs']\\n                    if metric=='missing_support':\\n                        values[method]=sum(len(r['measurement']['missing_support']) for r in pairs) if all('measurement' in r for r in pairs) else None\\n                    else:\\n                        key='dio_error_semitones' if metric=='DIO_error' else 'acf_error_semitones'\\n                        points=[r.get('pitch_gate',{}).get(key) for r in pairs]\\n                        values[method]=sum(points)/len(points) if all(x is not None for x in points) else None\\n            complete=all(x is not None for x in values.values())\\n            contrasts={key:values[candidate]-values[baseline] for key,baseline,candidate in [\\n                ('WORLD/native','native','postfilter'),('WORLD/voicing','voicing','voicing_postfilter'),\\n                ('HTS/native','hts_native','hts_postfilter'),('HTS/voicing','hts_voicing','hts_voicing_postfilter')]} if complete else {}\\n            factorial[metric]=dict(values=values,complete=complete,lower_is_better=True,postfilter_delta_at_each_LF0_renderer=contrasts,\\n                postfilter_main=sum(contrasts.values())/4 if complete else None,descriptive_only=True)\\n        secondary={}\\n        for method,e in engineering.items():\\n            secondary[method]={tracker:dict(missing_intervals=sum(len(x['secondary_diagnostic'][tracker]['missing_support']) for x in e['pairs']) if all('secondary_diagnostic' in x for x in e['pairs']) else None,qualified_for_Japanese_non_neural=False,used_for_selection=False) for tracker in ['harvest','centered_acf']}\\n        summary=dict(content=content, engineering=engineering,\\n            secondary_diagnostics=secondary, factorial_analysis=factorial, factorial_analysis_descriptive_only=True,\\n            qualifications=qualifications, negative_tests=negative_tests(),\\n            final_non_neural_runtime_verified=True, vocoder_LF0_research_only=True,\\n            perceptual_qualification=False, protected_confirmation_opened=False,\\n            quality_goal_completed=False)\\n        b.write_data(HERE/'summary.json',encode(summary),job)\\n        compact=dict(summary)\\n        compact['engineering']={m:{k:v for k,v in e.items() if k!='pairs'} for m,e in engineering.items()}\\n        compact['content']={m:{n:{k:v for k,v in result.items() if k!='pairs'} for n,result in engines.items()} for m,engines in content.items()}\\n        compact['detailed_summary_path']=str((HERE/'summary.json').relative_to(REPO))\\n        compact['detailed_summary_sha256']=digest(HERE/'summary.json')\\n        compact['individual_records_external']=True\\n        b.save(HERE/'aggregate-summary.json',compact,job)\\n    print(qualifications, flush=True)\\n    print(b.reconcile(), flush=True)\\n\\n\\nif __name__ == '__main__':\\n    main()\\n\",\"asr_worker.py\":\"\\\"\\\"\\\"固定モデル・固定正規化による256音声の評価。結果はpipeへ返す。\\\"\\\"\\\"\\nimport argparse\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport sys\\nimport tempfile\\nimport time\\nfrom math import gcd\\nfrom paths import *\\n\\n\\ndef main():\\n    parser = argparse.ArgumentParser()\\n    parser.add_argument('--engine', choices=['whisper', 'reazon'], required=True)\\n    name = parser.parse_args().engine\\n    assert Path(tempfile.gettempdir()).resolve() == Path(os.environ['TMPDIR']).resolve()\\n    engine = read(HERE / 'engine-contract.json')\\n    sys.path[:0] = [str(OLD), str(PILOT / '.cache/packages')]\\n    from diagnostics import normalize_text, edit_distance\\n    import numpy as np\\n    import pyopenjtalk\\n    from scipy import signal\\n    from scipy.io import wavfile\\n    if name == 'whisper':\\n        from faster_whisper import WhisperModel\\n        recognizer = WhisperModel(engine['whisper_path'], device='cpu', compute_type='int8',\\n                                 cpu_threads=4, local_files_only=True)\\n    else:\\n        import sherpa_onnx\\n        cache = PILOT / '.cache/reazonspeech'\\n        recognizer = sherpa_onnx.OfflineRecognizer.from_transducer(\\n            encoder=str(cache / 'encoder-epoch-99-avg-1.int8.onnx'),\\n            decoder=str(cache / 'decoder-epoch-99-avg-1.int8.onnx'),\\n            joiner=str(cache / 'joiner-epoch-99-avg-1.int8.onnx'), tokens=str(cache / 'tokens.txt'),\\n            num_threads=2, sample_rate=16000, feature_dim=80,\\n            decoding_method='greedy_search', provider='cpu')\\n    rows = []\\n    for item in read(HERE / 'render-manifest.json')['rows']:\\n        record = read(REPO / item['record'])\\n        assert digest(REPO / record['wav']) == record['wav_sha256']\\n        fs, raw = wavfile.read(REPO / record['wav'])\\n        assert raw.ndim == 1 and len(raw) / fs <= 30\\n        started = time.monotonic()\\n        if name == 'whisper':\\n            segments, _ = recognizer.transcribe(str(REPO / record['wav']), language='ja',\\n                beam_size=5, initial_prompt=None, condition_on_previous_text=False, vad_filter=False)\\n            hypothesis = ''.join(s.text for s in segments)\\n        else:\\n            audio = raw.astype(np.float32) / (32768. if raw.dtype == np.int16 else 1.)\\n            divisor = gcd(fs, 16000)\\n            audio = signal.resample_poly(audio, 16000 // divisor, fs // divisor).astype(np.float32)\\n            stream = recognizer.create_stream()\\n            stream.accept_waveform(16000, audio)\\n            recognizer.decode_stream(stream)\\n            hypothesis = stream.result.text\\n        ref = normalize_text(pyopenjtalk.g2p(record['text'], kana=True))\\n        pred = normalize_text(pyopenjtalk.g2p(hypothesis, kana=True)) if hypothesis else ''\\n        result = {k: record[k] for k in (\\n            'id', 'text', 'length', 'challenge_group', 'condition', 'variant', 'wav', 'wav_sha256')}\\n        result.update(status='completed', engine=name, ai_calls=1, hypothesis=hypothesis,\\n            reference_kana=ref, predicted_kana=pred, errors=edit_distance(ref, pred),\\n            characters=len(ref), duration_seconds=len(raw) / fs, seconds=time.monotonic() - started,\\n            protocol_sha256=digest(HERE / 'protocol.json'),\\n            engine_contract_sha256=digest(HERE / 'engine-contract.json'),\\n            evaluator_sha256=digest(Path(__file__)), quality_certified=False,\\n            used_in_optimization=False)\\n        rows.append(result)\\n        if len(rows) % 16 == 0:\\n            print(name, len(rows), '/256', file=sys.stderr, flush=True)\\n    assert len(rows) == 256\\n    print(json.dumps(dict(rows=rows, ai_calls=256, reused=0), ensure_ascii=False, allow_nan=False))\\n\\n\\nif __name__ == '__main__':\\n    main()\\n\",\"measurement.py\":\"\\\"\\\"\\\"固定時計のDIO支持と、独立な全体ACF測定。欠測を分母に残す。\\\"\\\"\\\"\\nimport numpy as np\\nimport pyworld\\nfrom acoustics import estimate_f0\\n\\nELIGIBLE = {'a', 'i', 'u', 'e', 'o', 'N', 'm', 'n', 'my', 'ny'}\\n\\n\\ndef local(f0, times, duration, indices):\\n    bounds = np.r_[0, np.cumsum(duration)] * .005\\n    rows = []\\n    for index in indices:\\n        mask = (times >= bounds[index * 5]) & (times < bounds[(index + 1) * 5])\\n        values = f0[mask & (f0 >= 70) & (f0 <= 800)]\\n        n = int(mask.sum())\\n        rows.append(dict(index=index, interval_frames=n, voiced_frames=len(values),\\n            support_complete=n > 0 and len(values) >= 3 and len(values) >= n * .5,\\n            median_hz=float(np.median(values)) if len(values) else None))\\n    return rows\\n\\n\\ndef measure(audio, duration, eligible, support=None):\\n    f0, times = pyworld.dio(audio.astype(float), 24000, f0_floor=70., f0_ceil=800., frame_period=5.)\\n    f0 = pyworld.stonemask(audio.astype(float), f0, times, 24000)\\n    native_rows = local(f0, times, duration, eligible)\\n    if support is None:\\n        support = [r['index'] for r in native_rows if r['support_complete']]\\n    local_rows = local(f0, times, duration, support)\\n    missing = [r['index'] for r in local_rows if not r['support_complete']]\\n    hop = 240\\n    rms = np.array([np.sqrt(np.mean(audio[i:i + hop].astype(float) ** 2))\\n                    for i in range(0, len(audio), hop)])\\n    active = np.flatnonzero(rms > max(1e-5, .05 * rms.max()))\\n    hz, confidence = (None, 0.)\\n    if len(active):\\n        hz, confidence = estimate_f0(audio[active[0] * hop:min(len(audio), (active[-1] + 1) * hop)],\\n                                     24000, minimum=70, maximum=800)\\n    return dict(dio_median_hz=float(np.median(f0[f0 > 0])) if (f0 > 0).any() else None,\\n                acf_hz=hz, acf_confidence=confidence, support=support,\\n                missing_support=missing, support_complete=len(support) >= 3 and not missing,\\n                local=local_rows, eligible_native_intervals=native_rows), f0, times\\n\\n\\ndef pitch_pass(value, target):\\n    def distance(hz):\\n        return float(abs(12 * np.log2(hz / target))) if hz is not None and hz > 0 else None\\n    dio, acf = distance(value['dio_median_hz']), distance(value['acf_hz'])\\n    return dict(dio_error_semitones=dio, acf_error_semitones=acf,\\n                passed=bool(dio is not None and acf is not None and dio <= 1. and acf <= 1.\\n                and value['acf_confidence'] >= .6 and value['support_complete']))\\n\\ndef secondary(audio,duration,support):\\n    from period_measurement import frame_acf\\n    x=np.ascontiguousarray(audio,dtype=np.float64)\\n    h,ht=pyworld.harvest(x,24000,f0_floor=70.,f0_ceil=800.,frame_period=5.)\\n    a,at,confidence=frame_acf(x)\\n    value={}\\n    for name,values,times in [('harvest',h,ht),('centered_acf',a,at)]:\\n        rows=local(values,times,duration,support)\\n        value[name]=dict(missing_support=[r['index'] for r in rows if not r['support_complete']],\\n            local=rows,median_hz=float(np.median(values[values>0])) if (values>0).any() else None,\\n            Japanese_non_neural_qualified=False,used_for_selection=False)\\n    return value,dict(harvest=h,harvest_times=ht,centered_acf=a,acf_times=at,acf_confidence=confidence)\\n\",\"test_controls.py\":\"\\\"\\\"\\\"変更対象の局所性・否定入力・AP恒等性を人工配列で検査する。\\\"\\\"\\\"\\nimport os,sys,tempfile,json\\nfrom pathlib import Path\\nassert Path(tempfile.gettempdir()).resolve()==Path(os.environ['TMPDIR']).resolve()\\nsys.path.insert(0,str(Path(__file__).resolve().parent/'runtime-bundle'))\\nimport numpy as np\\nfrom controls_v2 import fill_lf0,transform,ap_noise_power\\nlabels=['x-a+y','x-I+y','x-k+y','x-m+y','x-sil+y']\\nduration=np.ones(25,dtype=int)\\nx=np.full((25,1),-1e10)\\nx[[0,2,4,5,7,9,10,12,14,15,19],0]=np.log([200,220,240,200,220,240,200,220,240,200,240])\\ny,meta=fill_lf0(x,labels,duration)\\nassert meta['filled_frame_indices']==[1,3]\\nassert y[x[:,0]>0].tobytes()==x[x[:,0]>0].tobytes()\\nassert y[5:].tobytes()==x[5:].tobytes()\\nassert abs(y[1,0]-(x[0,0]+x[2,0])/2)<1e-15\\nnative=[np.zeros((25,35)),x.copy(),np.tile([0,1,0],(25,1))]\\nparams,control,error,passed=transform('combined',native,labels,duration,220.)\\njson.dumps(control,allow_nan=False)\\nassert passed and error<=2e-15 and np.array_equal(params[0],native[0]) and np.array_equal(params[2],native[2])\\nassert (x[1,0]<0) and params[1][1,0]>0 and params[1][6,0]<0\\nfor bad in [duration[:-1],np.zeros(25),duration*.5]:\\n    try: fill_lf0(x,labels,bad)\\n    except ValueError: pass\\n    else: raise AssertionError('不正durationを受理')\\nf0=np.array([0,220,280.]);power=np.ones((3,4));ap=np.array([[1.,1.,1.,1.],[.001,.1,.5,.99],[.2,.4,.6,.8]])\\nold=[a.tobytes() for a in [f0,power,ap]]\\nassert ap_noise_power(f0,power,ap,1.) is ap\\nhalf=ap_noise_power(f0,power,ap,.5)\\nassert half[0].tobytes()==ap[0].tobytes()\\nassert np.allclose(half[1:,1:]**2,ap[1:,1:]**2*.5,rtol=1e-15)\\nassert half[1,0]==.001 and old==[a.tobytes() for a in [f0,power,ap]]\\nprint(json.dumps(dict(original_voiced_preserved=True,eligible_only_fill=True,unvoiced_consonants_uppercase_pause_preserved=True,under_three_frames_not_filled=True,log_interpolation_verified=True,AP_identity_byte_exact=True,AP_power_half_with_floor=True,F0_SP_unchanged=True,bad_duration_rejected=True,actual_render_calls=0,quality_evidence=False)))\\n\",\"hts_arrays.py\":\"\\\"\\\"\\\"生成3streamをHTS pulse/noise MLSAへ直接渡す非ニューラル配列入口。\\\"\\\"\\\"\\nimport ctypes as C\\nfrom pathlib import Path\\nimport hashlib\\nimport numpy as np\\nfrom scipy import signal\\nimport local_renderer  # 対応版pyopenjtalk HTS symbolsをRTLD_GLOBALで初期化\\n_lib=C.CDLL(str(Path(__file__).resolve().parent/'hts_arrays.dylib'))\\n_fn=_lib.hts_arrays_render\\nP=C.POINTER(C.c_double);S=C.c_size_t\\n_fn.restype=C.c_int;_fn.argtypes=[P,P,P,S,S,S,P,S]\\ndef ah(x): return hashlib.sha256(np.asarray(x,dtype='<f8').tobytes()).hexdigest()\\ndef validated(params,settings):\\n    if len(params)!=3: raise ValueError('生成3stream必須')\\n    x=[np.ascontiguousarray(v,dtype=np.float64) for v in params]\\n    if any(v.ndim!=2 or not v.size or not np.isfinite(v).all() for v in x):\\n        raise ValueError('有限非空の2D配列を要求')\\n    if len({len(v) for v in x})!=1 or not 1<=len(x[0])<=6000 or x[0].shape[1]!=35 or x[1].shape[1]!=1 or not 1<=x[2].shape[1]<=63 or x[2].shape[1]%2!=1:\\n        raise ValueError('固定Meiの同フレームMCP35/LF01/奇数LPFを要求')\\n    voiced=x[1][:,0]>0\\n    if np.any(x[1][~voiced]!=-1e10) or np.any((np.exp(x[1][voiced,0])<70)|(np.exp(x[1][voiced,0])>800)):\\n        raise ValueError('LF0 sentinelまたは有声F0範囲が不正')\\n    expected=dict(stage=0.,use_log_gain=0.,sampling_frequency=48000.,fperiod=240.,alpha=.55,beta=0.,volume=1.,audio_buff_size=0.,stop=0.)\\n    if settings!=expected: raise ValueError('固定Mei設定だけを許可')\\n    return x\\ndef synthesize(params,settings):\\n    x=validated(params,settings);before=[ah(v) for v in x]\\n    raw=np.empty(len(x[0])*240,dtype=np.float64)\\n    if not _fn(*(v.ctypes.data_as(P) for v in x),len(x[0]),35,x[2].shape[1],raw.ctypes.data_as(P),len(raw)):\\n        raise RuntimeError('HTS配列vocoderの入力/有限性検査に不通過')\\n    assert [ah(v) for v in x]==before\\n    audio=signal.resample_poly(raw/32768.,1,2)\\n    n=min(round(.012*24000),len(audio)//2);env=np.sin(np.linspace(0,np.pi/2,n))**2\\n    audio[:n]*=env;audio[-n:]*=env[::-1]\\n    assert len(audio)==len(x[0])*120 and np.isfinite(audio).all()\\n    return audio,dict(renderer='HTS-pulse-noise-MLSA',input_parameter_hashes=before,input_streams_unchanged=True,\\n        frames_original=len(x[0]),fs=48000,output_fs=24000,sample_count_24k=len(audio),alpha=.55,beta=0.,volume=1.,stage=0,use_log_gain=False,\\n        clock='native全フレームを順次生成。先頭複製/末尾frame切りなし。',\\n        source='対応版HTS_Vocoder_initialize/synthesize/clear',saved_waveform_analysis_used=False,\\n        neural_model=False,utterance_lookup=False)\\n\",\"hts_arrays.c\":\"/* 対応版HTSヘッダと既存vocoderを使う全フレーム配列入口。BSD通知を同梱。 */\\n#include \\\"HTS_hidden.h\\\"\\n#include <math.h>\\n#include <stddef.h>\\n#include <string.h>\\nint hts_arrays_render(const double *mcp,const double *lf0,const double *lpf,\\n                      size_t frames,size_t nmcp,size_t nlpf,double *out,size_t samples) {\\n    if (!mcp || !lf0 || !lpf || !out || frames<1 || frames>6000 ||\\n        nmcp!=35 || nlpf<1 || nlpf>63 || nlpf%2!=1 || samples!=frames*240) return 0;\\n    for (size_t f=0;f<frames;f++) {\\n        if (!isfinite(lf0[f]) || (lf0[f]!=LZERO && (exp(lf0[f])<70 || exp(lf0[f])>800))) return 0;\\n        for (size_t j=0;j<nmcp;j++) if (!isfinite(mcp[f*nmcp+j])) return 0;\\n        for (size_t j=0;j<nlpf;j++) if (!isfinite(lpf[f*nlpf+j])) return 0;\\n    }\\n    HTS_Vocoder v;\\n    HTS_Vocoder_initialize(&v,nmcp-1,0,FALSE,48000,240);\\n    for (size_t f=0;f<frames;f++) {\\n        double mc[35],lp[63];\\n        memcpy(mc,mcp+f*nmcp,nmcp*sizeof(double));\\n        memcpy(lp,lpf+f*nlpf,nlpf*sizeof(double));\\n        HTS_Vocoder_synthesize(&v,nmcp-1,lf0[f],mc,nlpf,lp,.55,0.,1.,out+f*240,NULL);\\n    }\\n    HTS_Vocoder_clear(&v);\\n    for (size_t i=0;i<samples;i++) if (!isfinite(out[i])) return 0;\\n    return 1;\\n}\\n\",\"period_measurement.py\":\"\\\"\\\"\\\"事前固定の5ms時計で既知周期を検査。既存音声は診断だけに使う。\\\"\\\"\\\"\\nimport numpy as np\\nimport pyworld\\nfrom acoustics import estimate_f0\\nFS=24000\\ndef frame_acf(audio):\\n    times=np.arange(len(audio)//120+1)*.005;values=np.zeros(len(times));confidence=np.zeros(len(times))\\n    for i,t in enumerate(times):\\n        center=round(t*FS);start=center-720;stop=start+1440\\n        if start<0 or stop>len(audio):continue\\n        hz,score=estimate_f0(audio[start:stop],FS,minimum=70,maximum=800)\\n        confidence[i]=float(score)\\n        if hz is not None and score>=.6:values[i]=float(hz)\\n    return values,times,confidence\\ndef legacy_acf(audio):\\n    rms=np.array([np.sqrt(np.mean(audio[i:i+240].astype(float)**2)) for i in range(0,len(audio),240)])\\n    active=np.flatnonzero(rms>max(1e-5,.05*rms.max()))\\n    return estimate_f0(audio[active[0]*240:min(len(audio),(active[-1]+1)*240)],FS,minimum=70,maximum=800) if len(active) else (None,0.)\\ndef trackers(audio):\\n    x=np.ascontiguousarray(audio,dtype=np.float64)\\n    f,t=pyworld.dio(x,FS,f0_floor=70.,f0_ceil=800.,frame_period=5.)\\n    f=pyworld.stonemask(x,f,t,FS)\\n    h,ht=pyworld.harvest(x,FS,f0_floor=70.,f0_ceil=800.,frame_period=5.)\\n    a,at,confidence=frame_acf(x)\\n    hz,score=legacy_acf(x)\\n    return dict(dio=(f,t),harvest=(h,ht),centered_acf=(a,at)),dict(hz=hz,confidence=float(score),accepted=bool(hz is not None and score>=.6)),confidence\\ndef score_track(values,times,truth):\\n    accepted=(values>=70)&(values<=800)\\n    if truth['voiced']:\\n        core=(times>=truth['core_start'])&(times<truth['core_end'])\\n        unvoiced=(times<truth['voiced_start']-.02)|(times>=truth['voiced_end']+.02)\\n        target=truth['f0'];errors=np.full(len(values),np.inf)\\n        errors[accepted]=np.abs(12*np.log2(values[accepted]/target))\\n        correct=core&accepted&(errors<=1.)\\n        selected=values[core&accepted]\\n        median_error=float(abs(12*np.log2(np.median(selected)/target))) if len(selected) else None\\n        coverage=float(correct.sum()/core.sum()) if core.any() else 0.\\n        passed=bool(core.sum()>=3 and correct.sum()>=3 and coverage>=.9 and median_error is not None and median_error<=1.)\\n    else:\\n        core=np.zeros(len(values),bool);unvoiced=np.ones(len(values),bool);coverage=None;median_error=None;passed=False\\n    boundary=~(core|unvoiced)\\n    return dict(core_frames=int(core.sum()),correct_core_frames=int(correct.sum()) if truth['voiced'] else 0,coverage=coverage,median_error_semitones=median_error,core_pass=passed,unvoiced_frames=int(unvoiced.sum()),false_voiced_frames=int((accepted&unvoiced).sum()),boundary_frames=int(boundary.sum()),boundary_voiced_frames=int((accepted&boundary).sum()))\\ndef global_score(value,truth):\\n    error=float(abs(12*np.log2(value['hz']/truth['f0']))) if truth['voiced'] and value['accepted'] else None\\n    return dict(hz=value['hz'],confidence=value['confidence'],accepted=value['accepted'],error_semitones=error,core_pass=bool(truth['voiced'] and error is not None and error<=1.),negative_false_accept=bool(not truth['voiced'] and value['accepted']),support_qualification=False)\\ndef local(values,times,duration,indices):\\n    bounds=np.r_[0,np.cumsum(duration)]*.005;rows=[]\\n    for index in indices:\\n        mask=(times>=bounds[index*5])&(times<bounds[(index+1)*5]);accepted=values[mask&(values>=70)&(values<=800)];n=int(mask.sum())\\n        rows.append(dict(index=int(index),interval_frames=n,voiced_frames=len(accepted),support_complete=bool(n>0 and len(accepted)>=3 and len(accepted)>=n*.5),median_hz=float(np.median(accepted)) if len(accepted) else None))\\n    return rows\\n\",\"postfilter.c\":\"/* 対応HTS一次式のMCP後処理入口。元BSD通知をvendorと同梱する。 */\\n#define HTS_Vocoder_initialize PF_Vocoder_initialize\\n#define HTS_Vocoder_synthesize PF_Vocoder_synthesize\\n#define HTS_Vocoder_clear PF_Vocoder_clear\\n#include \\\"HTS_vocoder.c\\\"\\n#include <string.h>\\n#include <stddef.h>\\n/* β0の無変更とβ0.2の既存エネルギー補正を共有する。 */\\nint mcp_postfilter(const double *input,size_t frames,size_t cols,double beta,\\n                   double *output,double *before,double *after) {\\n    if (!input || !output || !before || !after || frames<1 || frames>6000 ||\\n        cols!=35 || (beta!=0. && beta!=.2)) return 0;\\n    for(size_t i=0;i<frames*cols;i++) if(!isfinite(input[i])) return 0;\\n    HTS_Vocoder v;\\n    PF_Vocoder_initialize(&v,34,0,FALSE,48000,240);\\n    for(size_t f=0;f<frames;f++){\\n        double b[35];\\n        memcpy(output+f*35,input+f*35,35*sizeof(double));\\n        HTS_mc2b(output+f*35,b,34,.55);\\n        before[f]=HTS_b2en(&v,b,34,.55);\\n        HTS_Vocoder_postfilter_mcp(&v,output+f*35,34,.55,beta);\\n        HTS_mc2b(output+f*35,b,34,.55);\\n        after[f]=HTS_b2en(&v,b,34,.55);\\n    }\\n    PF_Vocoder_clear(&v);\\n    for(size_t f=0;f<frames;f++) if(!isfinite(before[f]) || !isfinite(after[f]) ||\\n        before[f]<=0 || after[f]<=0) return 0;\\n    for(size_t i=0;i<frames*35;i++) if(!isfinite(output[i])) return 0;\\n    return 1;\\n}\\n/* 工学fixtureだけに使うHTS内部β付き生成。最終経路は前処理→β0生成。 */\\nint pf_reference_render(const double *mcp,const double *lf0,const double *lpf,\\n    size_t frames,size_t cols,size_t nlpf,double beta,double *out,size_t samples){\\n    if(!mcp || !lf0 || !lpf || !out || frames<1 || frames>6000 || cols!=35 ||\\n        nlpf<1 || nlpf>63 || nlpf%2!=1 || samples!=frames*240 || (beta!=0. && beta!=.2)) return 0;\\n    for(size_t f=0;f<frames;f++){\\n        if(!isfinite(lf0[f]) || (lf0[f]!=LZERO && (exp(lf0[f])<70 || exp(lf0[f])>800))) return 0;\\n        for(size_t j=0;j<35;j++) if(!isfinite(mcp[f*35+j])) return 0;\\n        for(size_t j=0;j<nlpf;j++) if(!isfinite(lpf[f*nlpf+j])) return 0;\\n    }\\n    HTS_Vocoder v;PF_Vocoder_initialize(&v,34,0,FALSE,48000,240);\\n    for(size_t f=0;f<frames;f++){\\n        double mc[35],lp[63];memcpy(mc,mcp+f*35,35*sizeof(double));\\n        memcpy(lp,lpf+f*nlpf,nlpf*sizeof(double));\\n        PF_Vocoder_synthesize(&v,34,lf0[f],mc,nlpf,lp,.55,beta,1.,out+f*240,NULL);\\n    }\\n    PF_Vocoder_clear(&v);\\n    for(size_t i=0;i<samples;i++) if(!isfinite(out[i])) return 0;\\n    return 1;\\n}\\n\",\"postfilter.py\":\"\\\"\\\"\\\"一次HTS式のMCPエネルギー補正。発話表・教師・録音を参照しない。\\\"\\\"\\\"\\nimport ctypes as C\\nfrom pathlib import Path\\nimport numpy as np\\nfrom scipy import signal\\nimport local_renderer\\nfrom hts_arrays import validated,ah\\n_lib=C.CDLL(str(Path(__file__).resolve().parent/'postfilter.dylib'))\\nP=C.POINTER(C.c_double);S=C.c_size_t\\n_fn=_lib.mcp_postfilter;_fn.restype=C.c_int;_fn.argtypes=[P,S,S,C.c_double,P,P,P]\\n_ref=_lib.pf_reference_render;_ref.restype=C.c_int;_ref.argtypes=[P,P,P,S,S,S,C.c_double,P,S]\\ndef transform_mcp(value,beta):\\n    x=np.ascontiguousarray(value,dtype=np.float64)\\n    if x.ndim!=2 or x.shape[1]!=35 or not 1<=len(x)<=6000 or not np.isfinite(x).all() or beta not in [0.,.2]:\\n        raise ValueError('有限MCP Nx35と登録済みβ0/0.2だけを許可')\\n    original=ah(x);y=np.empty_like(x);before=np.empty(len(x));after=np.empty(len(x))\\n    if not _fn(x.ctypes.data_as(P),len(x),35,beta,y.ctypes.data_as(P),before.ctypes.data_as(P),after.ctypes.data_as(P)):\\n        raise RuntimeError('MCP一次後処理の有限性検査に不通過')\\n    assert ah(x)==original\\n    error=float(np.max(np.abs(np.log(after/before))))\\n    invariant=bool(error<=1e-10)\\n    if beta==0.:assert y.tobytes()==x.tobytes()\\n    return y,dict(beta=float(beta),alpha=.55,frames=len(x),max_abs_log_energy_ratio=error,\\n        energy_invariant_pass=invariant,input_preserved=True,zero_beta_byte_exact=bool(beta==0.),\\n        energy_definition='対応版HTS_b2enの有限インパルス応答エネルギー。実波形の等ラウドネス保証ではない。',\\n        source='HTS_Vocoder_postfilter_mcp',utterance_lookup=0,neural=False)\\ndef reference_synthesize(params,settings,beta):\\n    x=validated(params,settings);before=[ah(v) for v in x];raw=np.empty(len(x[0])*240)\\n    if not _ref(*(v.ctypes.data_as(P) for v in x),len(x[0]),35,x[2].shape[1],beta,raw.ctypes.data_as(P),len(raw)):\\n        raise RuntimeError('一次HTS内部β付きfixtureが不正')\\n    assert [ah(v) for v in x]==before\\n    audio=signal.resample_poly(raw/32768.,1,2)\\n    n=min(round(.012*24000),len(audio)//2);env=np.sin(np.linspace(0,np.pi/2,n))**2\\n    audio[:n]*=env;audio[-n:]*=env[::-1]\\n    assert np.isfinite(audio).all()\\n    return audio\\n\",\"closeout.py\":\"\\\"\\\"\\\"全256比較・二ASR・独立性・費用を保持して封印する。\\\"\\\"\\\"\\nfrom paths import *\\nfrom controller import verify\\ndef main():\\n    verify();b=Budget();b.recover();assert not b.snapshot()['jobs']\\n    summary=read(HERE/'aggregate-summary.json')\\n    assert all(not v for v in [summary['perceptual_qualification'],summary['quality_goal_completed'],summary['protected_confirmation_opened']])\\n    with b.job(NAME,'audit','MCP後処理の全実体hash・費用・終了封印',reserve_bytes=4000000) as job:\\n        count=b.audit_data_hashes();state=b.snapshot();campaign=state['campaigns'][NAME]\\n        assert all(v['status']=='removed' and v['absence_verified'] for v in state.get('temporary_work',{}).values())\\n        assert all(campaign['counts'].get(k,0)<=v for k,v in campaign['limits'].items() if k not in ['seconds','bytes'])\\n        assert state['seconds']-campaign['start_seconds']<campaign['limits']['seconds'] and campaign['payload_bytes']<campaign['limits']['bytes']\\n        b.save(HERE/'cost-audit.json',dict(campaign=campaign,whole_cycle_counts=state['counts'],whole_cycle_seconds=state['seconds'],whole_cycle_write_bytes=state['write_bytes'],all_temporary_work_removed=True,planned_render=780,planned_DSP=1804,planned_AI=512,new_teacher_train_inverse_download_money=0),job)\\n        b.save(HERE/'summary-source-audit.json',dict(summary_sha256=digest(HERE/'summary.json'),aggregate_sha256=digest(HERE/'aggregate-summary.json'),source_sha256=digest(HERE/'summarize.py'),all_scientific_conditions_unchanged=True),job)\\n        b.save(HERE/'decision-audit.json',dict(qualifications=summary['qualifications'],selected=[k for k,v in summary['qualifications'].items() if v],scope='内容/指定制御の研究資格だけ。日本語非ニューラル知覚資格と独立P5は未達。',postfilter_contrasts=summary['factorial_analysis'],secondary_diagnostics=summary['secondary_diagnostics'],no_post_output_tuning=True,quality_goal_completed=False,protected_confirmation_opened=False,next='全256比較の欠測・悪化群・要因差を読み、70%見直しに従って残り枠の処理を選ぶ。'),job)\\n        lines=['# エネルギー補正付きMCP後処理の比較','', '新16文×2条件×8方式の256比較。全256通常／隔離組、CLI4件、二ASR各256件。','', '|方式|ピッチ/支持通過|E0通過|Whisper誤り|Reazon誤り|資格|','|---|---:|---:|---:|---:|---|']\\n        for method,q in summary['qualifications'].items():\\n            e=summary['engineering'][method];w=summary['content'][method]['whisper']['groups']['both/all'];r=summary['content'][method]['reazon']['groups']['both/all']\\n            lines.append(f\\\"|{method}|{e['pitch_pass_count']}/32|{e['E0_pass_count']}/32|{w['errors']}/{w['characters']}|{r['errors']}/{r['characters']}|{q}|\\\")\\n        lines+=['', '全33群の悪化・欠測はaggregate-summary.jsonに保持。βは出力前に0/0.2へ固定し、途中の係数探索なし。','MCPエネルギーは一次HTS内部式による補正で、波形の等ラウドネスや知覚品質の保証ではない。','追加Harvest/中心ACFは限定診断で、主判定と旧判定を変更しない。測定器4つを独立票とは扱わない。','保護最終確認は未開封、全体品質は未達。一時領域は全件削除・不存在確認済み。','']\\n        b.write(HERE/'report.md','\\\\n'.join(lines).encode(),job)\\n        hashes={str(p.relative_to(REPO)):digest(p) for p in HERE.rglob('*') if p.is_file()}\\n        b.save(HERE/'artifact-seal.json',dict(files=hashes,path_base='repository',external_hash_verified=count,experiment_completed=True,quality_certified=False,quality_goal_completed=False,budget_before_seal=b.snapshot()),job)\\n        b.save(HERE/'completion-audit.json',dict(files_verified=len(hashes),seal_sha256=digest(HERE/'artifact-seal.json'),all_temporary_work_removed=True,quality_goal_completed=False,protected_confirmation_opened=False),job)\\n    b.close_campaign(NAME)\\n    b.save(ROOT/'progress-0022.json',dict(latest_completed=str(HERE.relative_to(ROOT)),active_campaign=None,comparison_records=256,normal_isolated_pairs=256,CLI=4,ASR_records=512,qualifications=summary['qualifications'],quality_goal_completed=False,protected_confirmation_opened=False,all_temporary_work_removed=True,git_save_pending=True,next='要因差と残予算を確認し、有効な次処理へ継続。',budget=b.reconcile()))\\n    print(b.reconcile(),flush=True)\\nif __name__=='__main__':main()\\n\"}")
pool=json.loads("{\"candidate_pool_short\":[\"赤い椅子を窓の近くへ運びます。\",\"白い雲が畑の向こうに浮かびます。\",\"古い辞書を机の端へ置きます。\",\"細い糸で袋の口を結びます。\",\"丸い石が浅い川底に見えます。\",\"朝の市場で梨を三つ選びます。\",\"小さな鈴が廊下の奥で鳴ります。\",\"青い紙に明日の予定を書きます。\",\"木の箱を日陰の棚へ戻します。\",\"坂の上から港の灯りが見えます。\",\"雨の音を聞きながら豆を洗います。\",\"黄色い皿に蒸した芋を並べます。\",\"帰りの電車で短い手紙を読みます。\",\"庭の隅に新しい苗を植えます。\",\"空いた瓶を静かに床へ置きます。\",\"暖かい風が竹の葉を揺らします。\"],\"candidate_pool_long\":[\"赤い椅子を窓の近くへ運んでから、机の上の地図を広げて、明日歩く道を静かに確かめます。\",\"白い雲が畑の向こうに浮かんでいるので、橋の手前で足を止め、遠くの山の形を眺めます。\",\"古い辞書を机の端へ置いて、まだ意味の分からない言葉を調べながら、ノートの余白へ例文を書きます。\",\"細い糸で袋の口を結んだあと、棚に残っていた布をたたみ、箱の中の道具を一つずつ並べます。\",\"丸い石が浅い川底に見える場所で、流れる水の速さを確かめ、岸の草に隠れた小さな魚を探します。\",\"朝の市場で梨を三つ選び、隣の店で豆を買ってから、駅の前の広場を通って家へ戻ります。\",\"小さな鈴が廊下の奥で鳴ったので、読みかけの本を閉じて、窓から差し込む光の方へゆっくり歩きます。\",\"青い紙に明日の予定を書き、忘れやすい時間に丸を付けてから、玄関の壁に並ぶ写真の横へ貼ります。\",\"木の箱を日陰の棚へ戻したあと、道具に付いた砂を落とし、開いた扉の向こうから聞こえる声に耳を澄ませます。\",\"坂の上から港の灯りが見えてきたので、荷物を持ち直し、曲がり角に立つ時計を確かめながら道を下ります。\",\"雨の音を聞きながら豆を洗い、鍋に水を入れてから、窓辺に置いた花の葉に残る雫をそっと拭きます。\",\"黄色い皿に蒸した芋を並べ、湯気が少なくなるまで待ちながら、台所の引き出しから木の箸を二組取り出します。\",\"帰りの電車で短い手紙を読み、次の駅の名前が聞こえたところで、封筒を鞄の内側の小さな袋へ入れます。\",\"庭の隅に新しい苗を植え、乾いた土に少しずつ水を掛けてから、夕方の風が冷たくなる前に道具を片付けます。\",\"空いた瓶を静かに床へ置き、棚に残るラベルを確かめながら、明るい場所へ移した箱の中身を数えます。\",\"暖かい風が竹の葉を揺らすころ、家の前の細い道を歩き、川の近くにある古い橋までゆっくり向かいます。\"],\"origin\":\"この研究のために今回作成した日本語入力。保護最終確認の本文は参照せず、公開前の初出力以前に履歴照合する。\",\"protected_confirmation_opened\":false}")
def main():
    for name,source in sources.items():
        if name.endswith('.py'):ast.parse(source)
    b=Budget();b.recover();state=b.snapshot();assert not state['jobs']
    assert len(state['campaigns'])==18 and all(c['closed'] for c in state['campaigns'].values())
    reg=dict(read(ROOT/'next-mcp-postfilter-draft-0001.json'))
    old=read(PREVIOUS/'registration.json')
    reg['gates']['engineering']=reg['gates']['engineering'].replace('192','256')
    reg.update(input_pool_sha256=hashlib.sha256(encode(pool)).hexdigest(),fill_rule=old['fill_rule'],factor_rules='MCPだけへ一次HTS式β0/0.2を適用。LF0は既存native/voicing、LPF/state/MSD/variance/voice/gainは保持。WORLD AP=1、HTS内部β=0に固定して共有前処理を1回だけ適用。',upstream=old['upstream'],source_previous_seal_sha256=digest(PREVIOUS/'artifact-seal.json'),energy_log_ratio_tolerance=1e-10,energy_definition='対応HTS_b2enの内部近似エネルギー。波形の等ラウドネスではない。',technical_retry_per_job=2,technical_retry_campaign=10,scientific_tuning_after_output=False)
    remaining={k:state['limits'][k]-state['counts'].get(k,0) for k in ['render','dsp','ai','teacher','train','inverse','download']}
    assert all(reg['limits'][k]<=remaining[k] for k in remaining)
    assert state['limits']['seconds']-state['seconds']-14400>=reg['limits']['seconds']
    assert shutil.disk_usage(ROOT).free>=20000000000 and shutil.disk_usage(b.guard.root).free>=3500000000
    b.start_campaign(NAME,str(HERE.relative_to(ROOT)),reg['limits'],hashlib.sha256(encode(reg)).hexdigest())
    b.save(ROOT/'mcp-postfilter-candidate-pool-0001.json',pool)
    with b.job(NAME,'setup','MCP後処理の生成前登録・全ソース・一次版来歴',reserve_bytes=400000) as job:
        b.save(HERE/'registration.json',reg,job)
        for name,source in sources.items():b.write(HERE/name,source.encode(),job)
        for path in (PREVIOUS/'vendor').iterdir():
            if path.is_file():b.write(HERE/'vendor'/path.name,path.read_bytes(),job)
        upstream=ROOT/'campaigns/nas-source-identity-20261004-v1/upstream/HTS_vocoder.c'
        assert digest(upstream)==reg['source_postfilter_sha256']
        b.write(HERE/'vendor/HTS_vocoder.c',upstream.read_bytes(),job)
        b.write(HERE/'HTS-BSD-NOTICE.txt',(PREVIOUS/'HTS-BSD-NOTICE.txt').read_bytes(),job)
        b.save(HERE/'implementation-audit.json',dict(all_Python_AST_pass=True,sources={n:hashlib.sha256(v.encode()).hexdigest() for n,v in sources.items()},primary_source_sha256=digest(upstream),source_previous_seal_sha256=digest(PREVIOUS/'artifact-seal.json'),actual_render_calls=0,actual_signal_DSP_calls=0,expected_comparison=256,expected_normal_isolated_pairs=256,expected_ASR=512,no_new_download=True,protected_confirmation_opened=False),job)
    with b.locked():
        current=b._load();current.setdefault('continuation_checkpoint_history',[]).append(current['continuation_checkpoint'])
        current['continuation_checkpoint']=dict(id='mcp-postfilter-registered-20261008-0001',active_campaign=NAME,campaign_closed=False,next='build.py → prepare.py → preflight.py static/compat → controller.py comparison/isolate/asr → summarize.py → closeout.py',protected_confirmation_opened=False,quality_goal_completed=False,git_save_pending=True);b._write_state(current)
    print(b.reconcile(),flush=True)
if __name__=='__main__':main()
